<?php
$reservations=all('SELECT r.*,i.code,i.name,i.unit FROM stock_reservations r JOIN stock_items i ON i.id=r.item_id WHERE r.order_id=? ORDER BY r.id DESC',[$id]);
$movements=all('SELECT m.*,i.code,i.name,i.unit FROM stock_movements m JOIN stock_items i ON i.id=m.item_id WHERE m.order_id=? ORDER BY m.id DESC LIMIT 50',[$id]);
?><section class="panel padded commerce-block"><div class="panel-heading compact"><div><h2>Matières de la commande</h2><p>Réservez depuis la fiche matière. Consommez ou libérez les réservations avant de livrer / annuler.</p></div><a class="btn secondary" href="<?=e(url('stock'))?>">Ouvrir le stock →</a></div><?php if(!$reservations&&!$movements):?><p class="muted small">Aucune matière liée à cette commande.</p><?php else:?><div class="table-scroll"><table><thead><tr><th>MATIÈRE</th><th>QUANTITÉ</th><th>RÉSERVATION</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($reservations as $r):?><tr><td><a class="record-title" href="<?=e(url('stock_form',['id'=>$r['item_id']]))?>"><?=e($r['name'])?></a><small class="subline"><?=e($r['code'])?></small></td><td><?=e($r['quantity'].' '.$r['unit'])?></td><td><?=e($r['state'])?></td><td><div class="row-actions"><?php if($r['state']==='Active'):foreach(['Consommée'=>'Consommer','Libérée'=>'Libérer'] as $state=>$label):?><form method="post" data-confirm="<?=e($state==='Consommée'?'Consommer cette réservation et créer une sortie de stock ?':'Libérer cette réservation ?')?>"><?=csrf()?><input type="hidden" name="action" value="reservation_resolve"><input type="hidden" name="reservation_id" value="<?=(int)$r['id']?>"><input type="hidden" name="state" value="<?=e($state)?>"><button class="text-button"><?=e($label)?></button></form><?php endforeach;endif?></div></td></tr><?php endforeach?></tbody></table></div><?php if($movements):?><h3 class="commerce-block">Derniers mouvements liés</h3><div class="table-scroll"><table><thead><tr><th>DATE</th><th>MATIÈRE</th><th>OPÉRATION</th><th>QUANTITÉ</th><th>MOTIF</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=e(localDate($m['created_at']))?></td><td><?=e($m['name'])?></td><td><?=e($m['kind'])?></td><td><?=($m['direction']>0?'+':'−').e($m['quantity'].' '.$m['unit'])?></td><td><?=e($m['reason'])?></td></tr><?php endforeach?></tbody></table></div><?php endif;endif?></section>
